        return {'success': True, 'message': 'No files to compress.', 'failed_files': []}
    failed_files = []
    for f in files:
        src_path = os.path.join(src_folder, f)
        try:
            result = subprocess.run(['gzip', src_path], capture_output=True)
            if result.returncode != 0:
                failed_files.append(f)
                continue
            gz_path = src_path + '.gz'
            if os.path.exists(gz_path):
                shutil.move(gz_path, os.path.join(dst_folder, f + '.gz'))
        except Exception:
            failed_files.append(f)
    success = len(failed_files) == 0
    message = 'All files compressed and moved successfully.' if success else f'Failed to compress or move the following files: {", ".join(failed_files)}'
    return {'success': success, 'message': message, 'failed_files': failed_files}
